// Builds vendor/jsx_transform.cjs: sucrase (version 3.35.1, MIT, see LICENSE-sucrase) bundled into one
// CommonJS file that desk_raw.py runs with node. It reads JSX source on stdin and prints JSON, either
// {"code": "..."} or {"error": "...", "line": N}. Only the jsx transform is used, classic runtime, pragma __h.
//
// Rebuild (needs `npm install` in skills/routineos/assets/desk first):
//   node skills/routineos/scripts/vendor/build_jsx_transform.mjs
import { writeFileSync, statSync } from "node:fs";
import { createRequire } from "node:module";
import { dirname, join } from "node:path";
import { fileURLToPath, pathToFileURL } from "node:url";

const HERE = dirname(fileURLToPath(import.meta.url));
const DESK = join(HERE, "..", "..", "assets", "desk");
const OUT = join(HERE, "jsx_transform.cjs");
const deskRequire = createRequire(join(DESK, "package.json"));
const SUCRASE_VERSION = deskRequire("sucrase/package.json").version;
if (SUCRASE_VERSION !== "3.35.1") throw new Error("expected sucrase 3.35.1 in desk/node_modules, found " + SUCRASE_VERSION);
const { rolldown } = await import(pathToFileURL(deskRequire.resolve("rolldown")).href);

const ENTRY = `
import { transform } from "sucrase";
import { readFileSync } from "node:fs";
let out;
try {
  const code = transform(readFileSync(0, "utf8"), {
    transforms: ["jsx"], jsxRuntime: "classic", jsxPragma: "__h", jsxFragmentPragma: "__F", production: true,
  }).code;
  out = { code };
} catch (e) {
  out = { error: String((e && e.message) || e), line: e && e.loc && typeof e.loc.line === "number" ? e.loc.line : null };
}
process.stdout.write(JSON.stringify(out));
`;

const BANNER = [
  "/* jsx_transform.cjs: generated by build_jsx_transform.mjs, do not edit.",
  " * Bundles sucrase " + SUCRASE_VERSION + " (MIT, Copyright (c) 2012-2018 various contributors, see LICENSE-sucrase).",
  " * Rebuild: node skills/routineos/scripts/vendor/build_jsx_transform.mjs",
  " */",
].join("\n");

const bundle = await rolldown({
  input: "jsx-transform-entry",
  platform: "node",
  plugins: [{
    name: "entry",
    resolveId(id) {
      if (id === "jsx-transform-entry") return id;
      if (id === "sucrase") return deskRequire.resolve("sucrase");
      return null;
    },
    load(id) { return id === "jsx-transform-entry" ? ENTRY : null; },
  }],
});
const { output } = await bundle.generate({ format: "cjs", minify: true, codeSplitting: false });
await bundle.close();
if (output.length !== 1) throw new Error("expected one output chunk, got " + output.length);
// Keep the file ASCII (sucrase's HTML entity table holds dash characters the repo text scans refuse). A \uXXXX
// escape means the same character in strings, template literals and regular expressions.
const ascii = output[0].code.replace(/[^\x00-\x7f]/g, (c) => "\\u" + c.charCodeAt(0).toString(16).padStart(4, "0"));
writeFileSync(OUT, BANNER + "\n" + ascii);
console.log(OUT + " " + statSync(OUT).size + " bytes");
